import React from 'react';
import {
  render,
  screen,
  userEvent,
  waitFor,
  act,
  fireEvent,
  cleanup,
} from '@testing-library/react-native';
import { Alert } from 'react-native';
import VerifyScreen from '@/app/(auth)/verify';
import { supabase } from '@/lib/supabase';
import { useRouter, useLocalSearchParams } from 'expo-router';
import { useAuth } from '@/context/AuthContext';

describe('VerifyScreen', () => {
  const mockPush = jest.fn();
  const mockReplace = jest.fn();
  const mockBack = jest.fn();
  const mockCanGoBack = jest.fn();
  const mockSetIsRecovering = jest.fn();
  const alertSpy = jest.spyOn(Alert, 'alert');

  beforeEach(() => {
    jest.clearAllMocks();
    mockCanGoBack.mockReturnValue(true);
    (useRouter as jest.Mock).mockReturnValue({
      push: mockPush,
      replace: mockReplace,
      back: mockBack,
      canGoBack: mockCanGoBack,
    });
    (useLocalSearchParams as jest.Mock).mockReturnValue({
      email: 'test@ufl.edu',
      mode: 'signup',
    });
    (useAuth as jest.Mock).mockReturnValue({
      setIsRecovering: mockSetIsRecovering,
      signOut: jest.fn(),
    });
  });

  afterEach(async () => {
    await cleanup();
  });

  describe('UI & Navigation', () => {
    it('renders titles and instructions with the target email', async () => {
      await render(<VerifyScreen />);

      expect(screen.getByText('Check your email')).toBeTruthy();
      expect(screen.getByText(/test@ufl\.edu/)).toBeTruthy();
      expect(screen.getByText('Enter the 6-digit code sent to test@ufl.edu.')).toBeTruthy();
      expect(screen.getByText('Verify')).toBeTruthy();
      expect(screen.getByText(/Resend code/)).toBeTruthy();
    });

    it('renders recovery instructions when mode is recovery', async () => {
      (useLocalSearchParams as jest.Mock).mockReturnValue({
        email: 'recovery@ufl.edu',
        mode: 'recovery',
      });
      await render(<VerifyScreen />);

      expect(
        screen.getByText("If an account for recovery@ufl.edu exists, we've sent a 6-digit code."),
      ).toBeTruthy();
    });

    it('navigates back when back button pressed and canGoBack is true', async () => {
      const user = userEvent.setup();
      mockCanGoBack.mockReturnValue(true);
      await render(<VerifyScreen />);

      await user.press(screen.getByLabelText('Go back'));
      expect(mockBack).toHaveBeenCalled();
    });

    it('replaces to signup when back pressed, cannot go back, and mode is signup', async () => {
      const user = userEvent.setup();
      mockCanGoBack.mockReturnValue(false);
      (useLocalSearchParams as jest.Mock).mockReturnValue({
        email: 'test@ufl.edu',
        mode: 'signup',
      });
      await render(<VerifyScreen />);

      await user.press(screen.getByLabelText('Go back'));
      expect(mockReplace).toHaveBeenCalledWith('/(auth)/signup');
    });

    it('replaces to forgot-password when back pressed, cannot go back, and mode is recovery', async () => {
      const user = userEvent.setup();
      mockCanGoBack.mockReturnValue(false);
      (useLocalSearchParams as jest.Mock).mockReturnValue({
        email: 'test@ufl.edu',
        mode: 'recovery',
      });
      await render(<VerifyScreen />);

      await user.press(screen.getByLabelText('Go back'));
      expect(mockReplace).toHaveBeenCalledWith('/(auth)/forgot-password');
    });
  });

  describe('Verification flows', () => {
    it('disables verify button when code length is less than 6', async () => {
      const user = userEvent.setup();
      await render(<VerifyScreen />);

      const verifyButton = screen.getByRole('button', { name: 'Verify' });
      expect(verifyButton.props.accessibilityState.disabled).toBe(true);

      const otpInput = screen.getByDisplayValue('');
      await user.type(otpInput, '123');

      expect(verifyButton.props.accessibilityState.disabled).toBe(true);
    });

    it('auto-submits OTP on typing 6 digits in signup mode', async () => {
      (supabase.auth.verifyOtp as jest.Mock).mockResolvedValueOnce({
        data: { user: { id: '123' }, session: {} },
        error: null,
      });

      const user = userEvent.setup();
      await render(<VerifyScreen />);

      const otpInput = screen.getByDisplayValue('');
      await user.type(otpInput, '654321');

      await waitFor(() => {
        expect(supabase.auth.verifyOtp).toHaveBeenCalledWith({
          email: 'test@ufl.edu',
          token: '654321',
          type: 'signup',
        });
      });
      expect(mockSetIsRecovering).not.toHaveBeenCalled();
      expect(mockReplace).not.toHaveBeenCalled();
    });

    it('sets isRecovering and navigates to reset-password on successful recovery verification', async () => {
      (useLocalSearchParams as jest.Mock).mockReturnValue({
        email: 'recovery@ufl.edu',
        mode: 'recovery',
      });
      (supabase.auth.verifyOtp as jest.Mock).mockResolvedValueOnce({
        data: { user: { id: '123' }, session: {} },
        error: null,
      });

      const user = userEvent.setup();
      await render(<VerifyScreen />);

      const otpInput = screen.getByDisplayValue('');
      await user.type(otpInput, '112233');

      await waitFor(() => {
        expect(mockSetIsRecovering).toHaveBeenCalledWith(true);
        expect(supabase.auth.verifyOtp).toHaveBeenCalledWith({
          email: 'recovery@ufl.edu',
          token: '112233',
          type: 'recovery',
        });
        expect(mockReplace).toHaveBeenCalledWith('/(auth)/reset-password');
      });
    });

    it('handles verification error and resets isRecovering if in recovery mode', async () => {
      (useLocalSearchParams as jest.Mock).mockReturnValue({
        email: 'recovery@ufl.edu',
        mode: 'recovery',
      });
      (supabase.auth.verifyOtp as jest.Mock).mockResolvedValueOnce({
        data: null,
        error: { message: 'Invalid or expired OTP' },
      });

      const user = userEvent.setup();
      await render(<VerifyScreen />);

      const otpInput = screen.getByDisplayValue('');
      await user.type(otpInput, '999999');

      await waitFor(() => {
        expect(mockSetIsRecovering).toHaveBeenCalledWith(false);
        expect(alertSpy).toHaveBeenCalledWith(
          expect.stringMatching(/error|fail|invalid/i),
          expect.any(String),
        );
        expect(mockReplace).not.toHaveBeenCalled();
      });
    });
  });

  describe('Resend flow', () => {
    beforeEach(() => {
      jest.useFakeTimers();
    });

    afterEach(async () => {
      await cleanup();
      jest.clearAllTimers();
      jest.useRealTimers();
    });

    it('resends verification code for signup when cooldown finishes', async () => {
      (useLocalSearchParams as jest.Mock).mockReturnValue({
        email: 'test@ufl.edu',
        mode: 'signup',
      });
      (supabase.auth.resend as jest.Mock).mockResolvedValueOnce({
        error: null,
      });

      await render(<VerifyScreen />);

      expect(screen.getByText('Resend code (60s)')).toBeTruthy();

      await act(async () => {
        jest.advanceTimersByTime(60000);
      });

      expect(screen.getByText('Resend code')).toBeTruthy();

      await act(async () => {
        fireEvent.press(screen.getByText('Resend code'));
      });

      expect(supabase.auth.resend).toHaveBeenCalledWith({
        type: 'signup',
        email: 'test@ufl.edu',
      });
      expect(alertSpy).toHaveBeenCalledWith(
        expect.stringMatching(/sent|success/i),
        expect.any(String),
      );
    });

    it('resends password recovery email when mode is recovery', async () => {
      (useLocalSearchParams as jest.Mock).mockReturnValue({
        email: 'recovery@ufl.edu',
        mode: 'recovery',
      });
      (supabase.auth.resetPasswordForEmail as jest.Mock).mockResolvedValueOnce({
        error: null,
      });

      await render(<VerifyScreen />);

      await act(async () => {
        jest.advanceTimersByTime(60000);
      });

      expect(screen.getByText('Resend code')).toBeTruthy();

      await act(async () => {
        fireEvent.press(screen.getByText('Resend code'));
      });

      expect(supabase.auth.resetPasswordForEmail).toHaveBeenCalledWith('recovery@ufl.edu');
      expect(alertSpy).toHaveBeenCalledWith(
        expect.stringMatching(/sent|success/i),
        expect.any(String),
      );
    });

    it('shows alert if resend returns an error', async () => {
      (useLocalSearchParams as jest.Mock).mockReturnValue({
        email: 'test@ufl.edu',
        mode: 'signup',
      });
      (supabase.auth.resend as jest.Mock).mockResolvedValueOnce({
        error: { message: 'Rate limit exceeded' },
      });

      await render(<VerifyScreen />);

      await act(async () => {
        jest.advanceTimersByTime(60000);
      });

      expect(screen.getByText('Resend code')).toBeTruthy();

      await act(async () => {
        fireEvent.press(screen.getByText('Resend code'));
      });

      expect(alertSpy).toHaveBeenCalledWith(
        expect.stringMatching(/error|fail|could not/i),
        expect.any(String),
      );
    });
  });
});
